"use client";

import { FlowDiagram } from "@diax/react";
import {
  DataStoreNode,
  DiagramFrame,
  EvidenceNode,
  NodeBadge,
  SystemNode,
} from "@diax/ui-react/presentation";
import type { DiaxGroup, DiaxNode, DiaxRelation } from "diax";
import { BookOpenCheck, DatabaseZap, SearchCheck } from "lucide-react";
import type { KeyboardEvent, ReactNode } from "react";

const nodeClass = "w-[176px] max-w-[176px] [--diax-node-radius:2px]";

const nodes = [
  system("question", "Reader question", "Application input", ["intent", "tenant"], "info"),
  system("guard", "Request policy", "Safety boundary", ["auth", "scope", "PII"], "warning"),
  system(
    "orchestrator",
    "Retrieval orchestrator",
    "Query runtime",
    ["plan", "budget", "trace"],
    "accent",
  ),
  store("semantic-cache", "Semantic cache", "TTL + policy key", ["safe response", "source set"]),
  system("query-embed", "Query embedding", "Model boundary", ["normalized vector"], "neutral"),
  store("vector-store", "Knowledge index", "Vector + metadata", ["chunk", "source", "ACL"]),
  system("retrieve", "Candidate retrieval", "Search stage", ["top-k", "ACL filter"], "info"),
  system("rerank", "Evidence reranker", "Ranking stage", ["relevance", "diversity"], "accent"),
  system("answer", "Grounded answer", "Generation stage", ["claim", "citation"], "success"),
  {
    id: "evidence",
    content: (
      <EvidenceNode
        className={nodeClass}
        title="Citation receipt"
        source="document revision + chunk ID"
        sourceLabel="Trace"
        strength="high"
        description="Every material claim retains the exact retrieved source used to compose it."
      />
    ),
  },
  system("ingest", "Source intake", "Index pipeline", ["docs", "tickets", "runbooks"], "neutral"),
  system("chunk", "Semantic chunking", "Transform stage", ["section", "overlap"], "info"),
  system("doc-embed", "Document embedding", "Model boundary", ["batch", "revision"], "neutral"),
] satisfies readonly DiaxNode<ReactNode>[];

const relations = [
  relation("question-guard", "question", "guard", "request"),
  relation("guard-orchestrator", "guard", "orchestrator", "authorized intent"),
  relation("orchestrator-cache", "orchestrator", "semantic-cache", "policy-aware lookup"),
  relation("cache-orchestrator", "semantic-cache", "orchestrator", "safe hit"),
  relation("orchestrator-query-embed", "orchestrator", "query-embed", "search plan"),
  relation("query-embed-vector", "query-embed", "vector-store", "similarity query"),
  relation("vector-retrieve", "vector-store", "retrieve", "scoped candidates"),
  relation("retrieve-rerank", "retrieve", "rerank", "top-k passages"),
  relation("rerank-orchestrator", "rerank", "orchestrator", "ranked evidence"),
  relation("orchestrator-answer", "orchestrator", "answer", "grounded prompt"),
  relation("answer-evidence", "answer", "evidence", "claims + citations"),
  relation("ingest-chunk", "ingest", "chunk", "versioned source"),
  relation("chunk-doc-embed", "chunk", "doc-embed", "semantic units"),
  relation("doc-embed-vector", "doc-embed", "vector-store", "upsert revision"),
] satisfies readonly DiaxRelation<ReactNode>[];

const groups = [
  {
    id: "rag-system",
    label: <GroupLabel index="00">Grounded answer system</GroupLabel>,
    nodeIds: [],
  },
  {
    id: "query-runtime",
    parentId: "rag-system",
    label: <GroupLabel index="01">Online question path</GroupLabel>,
    nodeIds: [
      "question",
      "guard",
      "orchestrator",
      "semantic-cache",
      "query-embed",
      "retrieve",
      "rerank",
      "answer",
      "evidence",
    ],
  },
  {
    id: "index-pipeline",
    parentId: "rag-system",
    label: <GroupLabel index="02">Versioned knowledge path</GroupLabel>,
    nodeIds: ["ingest", "chunk", "doc-embed", "vector-store"],
  },
] satisfies readonly DiaxGroup<ReactNode>[];

export default function RagGroundingSystem() {
  return (
    <DiagramFrame
      data-showcase-corpus="rag-grounding-system"
      eyebrow="AI architecture · Automatic topology"
      title="A grounded answer has two supply chains"
      description="The online question path consumes a separately versioned knowledge path. DiaX owns their topology, nested boundaries and feedback routes."
      icon={<BookOpenCheck aria-hidden="true" />}
      caption="The cache can return to orchestration, but every delivered claim still terminates in a citation receipt."
      className="w-full max-w-[1120px] [--diax-accent:#176d68] [--diax-frame-bg:#f0ede4] [--diax-frame-radius:2px] [--diax-frame-shadow:none] [--diax-node-bg:#fffdf8] [--diax-node-border:#9ea9a5] [--diax-node-shadow:none] [--diax-node-text:#17272b] [--diax-ui-radius:2px]"
    >
      <div className="mb-4 grid border-y border-[#aeb6b0] md:grid-cols-3">
        <SystemFact
          icon={<SearchCheck aria-hidden="true" />}
          label="Online path"
          value="9 stages"
        />
        <SystemFact icon={<DatabaseZap aria-hidden="true" />} label="Index path" value="4 stages" />
        <SystemFact icon={<BookOpenCheck aria-hidden="true" />} label="Manual geometry" value="0" />
      </div>

      <div className="mb-2 flex items-center justify-between gap-3 text-[11px] leading-5 text-[#52605d] sm:hidden">
        <span>Wide topology map</span>
        <span
          aria-hidden="true"
          className="font-mono font-semibold uppercase tracking-[0.06em] text-[#176d68]"
        >
          Scroll →
        </span>
      </div>

      <section
        data-diax-reading-canvas
        className="overflow-x-auto overscroll-x-contain border border-[#aeb6b0] bg-[#f8f5ed] p-3 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#176d68] sm:p-5"
        aria-label="Grounded answer retrieval and ingestion architecture. Scroll horizontally to inspect the complete topology."
        // biome-ignore lint/a11y/noNoninteractiveTabindex: this overflow region must remain keyboard-scrollable in browsers that do not auto-focus it.
        tabIndex={0}
        onKeyDown={scrollTopologyOnArrow}
      >
        <FlowDiagram
          nodes={nodes}
          relations={relations}
          groups={groups}
          direction="horizontal"
          density="compact"
          pathType="orthogonal"
          strokeColor="#526d6b"
          highlightOnHover
          className="min-w-[1020px] [--diax-group-background:rgb(23_109_104_/_0.025)] [--diax-group-border:#8da8a4] [--diax-group-label-background:#f8f5ed] [--diax-group-label-inset:14px] [--diax-group-radius:2px]"
          renderEdgeLabel={(label) => <RelationLabel>{label}</RelationLabel>}
        />
      </section>

      <p className="m-0 mt-4 border-l-[3px] border-[#b65d3a] pl-3 text-xs leading-relaxed text-[#52605d]">
        Retrieval is not trusted merely because it returned text. Authorization constrains search,
        revisions constrain the index, and citation identity constrains the final answer.
      </p>
    </DiagramFrame>
  );
}

function system(
  id: string,
  name: string,
  kind: string,
  tags: readonly string[],
  tone: "neutral" | "accent" | "info" | "success" | "warning",
): DiaxNode<ReactNode> {
  return {
    id,
    content: (
      <SystemNode
        className={nodeClass}
        name={name}
        kind={kind}
        tags={tags}
        tone={tone}
        status={tone === "warning" ? "degraded" : tone === "success" ? "healthy" : undefined}
        statusLabel={
          tone === "warning" ? "policy gate" : tone === "success" ? "grounded" : undefined
        }
      />
    ),
  };
}

function store(
  id: string,
  name: string,
  engine: string,
  entries: readonly string[],
): DiaxNode<ReactNode> {
  return {
    id,
    content: <DataStoreNode className={nodeClass} name={name} engine={engine} entries={entries} />,
  };
}

function relation(id: string, from: string, to: string, label: string): DiaxRelation<ReactNode> {
  return {
    id,
    from,
    to,
    label,
    targetMarker: "arrow",
    gap: 7,
  };
}

function scrollTopologyOnArrow(event: KeyboardEvent<HTMLElement>) {
  if (event.target !== event.currentTarget) return;
  const direction = event.key === "ArrowRight" ? 1 : event.key === "ArrowLeft" ? -1 : 0;
  if (direction === 0) return;
  event.preventDefault();
  event.currentTarget.scrollBy({
    behavior: "auto",
    left: direction * Math.max(96, Math.round(event.currentTarget.clientWidth * 0.75)),
  });
}

function GroupLabel({ index, children }: { index: string; children: ReactNode }) {
  return (
    <span className="inline-flex items-center gap-2 whitespace-nowrap text-[#234643]">
      <NodeBadge tone="info">{index}</NodeBadge>
      <strong className="font-mono text-[11px] uppercase tracking-[0.08em]">{children}</strong>
    </span>
  );
}

function RelationLabel({ children }: { children: ReactNode }) {
  return (
    <span className="border border-[#91a19d] bg-[#fffdf8] px-1.5 py-0.5 font-mono text-[11px] font-semibold text-[#345451]">
      {children}
    </span>
  );
}

function SystemFact({ icon, label, value }: { icon: ReactNode; label: string; value: string }) {
  return (
    <div className="flex items-center gap-3 border-[#aeb6b0] px-3 py-3 md:border-l md:first:border-l-0">
      <span className="text-[#176d68] [&>svg]:size-4">{icon}</span>
      <span>
        <span className="block font-mono text-[10px] uppercase tracking-[0.08em] text-[#687470]">
          {label}
        </span>
        <strong className="block text-sm text-[#17272b]">{value}</strong>
      </span>
    </div>
  );
}
